use std::collections::HashMap;

/// Parses a line like 'key=value; key2=value2' into a HashMap<String, String>.
/// Keys and values are trimmed of whitespace. Empty keys or values are skipped.
pub fn parse_key_value_pairs(input: &str) -> HashMap<String, String> {
    let mut map = HashMap::new();

    for pair in input.split(';') {
        let pair = pair.trim();
        if pair.is_empty() {
            continue;
        }

        if let Some((key, value)) = pair.split_once('=') {
            let key = key.trim().to_string();
            let value = value.trim().to_string();

            if !key.is_empty() {
                map.insert(key, value);
            }
        }
    }

    map
